'use client'

import { defineFieldRenderer, formatBytes, uploadFile } from '@10x-media/form-builder/react'
import { type ChangeEvent, useId, useState } from 'react'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'

const typesOf = (mimeTypes: unknown): string[] => {
	if (!Array.isArray(mimeTypes)) {
		return []
	}
	return mimeTypes.filter((entry): entry is string => typeof entry === 'string')
}

export const fileField = defineFieldRenderer<string | number>(
	({ field, name, value, onChange, onBlur, errors, required, disabled }) => {
		const id = useId()
		const describedById = `${id}-desc`
		const label = typeof field.label === 'string' ? field.label : undefined
		const description = typeof field.description === 'string' ? field.description : undefined
		// Stamped server-side onto the block from the plugin's `uploads.collection` config.
		const collection =
			typeof field.uploadsCollection === 'string' ? field.uploadsCollection : undefined
		const types = typesOf(field.mimeTypes)
		const accept = types.length > 0 ? types.join(',') : undefined
		// Zero is a real limit, matching resolveFileRef server-side (filesize > maxSize rejects any non-empty file).
		const maxSize =
			typeof field.maxSize === 'number' && field.maxSize >= 0 ? field.maxSize : undefined
		const hints = [
			types.length > 0 ? `Accepted: ${types.join(', ')}` : undefined,
			maxSize !== undefined ? `Max size: ${formatBytes(maxSize)}` : undefined,
		].filter((hint): hint is string => typeof hint === 'string')

		const [uploading, setUploading] = useState(false)
		const [filename, setFilename] = useState<string | undefined>(undefined)
		const [localError, setLocalError] = useState<string | undefined>(undefined)
		const hasValue = value !== undefined && value !== null && value !== ''
		const displayName = filename ?? (hasValue ? 'Uploaded file' : undefined)
		const allErrors = localError ? [...errors, localError] : errors
		const invalid = allErrors.length > 0

		const handleChange = async (event: ChangeEvent<HTMLInputElement>) => {
			const selected = event.target.files?.[0]
			if (!selected) {
				return
			}
			if (maxSize !== undefined && selected.size > maxSize) {
				setLocalError(`File is too large (max ${formatBytes(maxSize)})`)
				return
			}
			if (!collection) {
				setLocalError('Upload failed')
				return
			}
			setUploading(true)
			setLocalError(undefined)
			const result = await uploadFile({ file: selected, collection })
			setUploading(false)
			if (result.ok) {
				setFilename(selected.name)
				onChange(result.id)
			} else {
				setLocalError(result.message ?? 'Upload failed')
			}
		}

		const clear = () => {
			setFilename(undefined)
			setLocalError(undefined)
			onChange('')
		}

		return (
			<div className="grid gap-2">
				{label ? (
					<Label htmlFor={id}>
						{label}
						{required ? (
							<span aria-hidden className="text-destructive">
								{' *'}
							</span>
						) : null}
					</Label>
				) : null}
				<input
					id={id}
					name={name}
					type="file"
					accept={accept}
					disabled={disabled || uploading}
					aria-invalid={invalid || undefined}
					aria-describedby={describedById}
					className={cn('text-sm', invalid && 'text-destructive')}
					onChange={(event) => {
						void handleChange(event)
					}}
					onBlur={onBlur}
				/>
				{hints.length > 0 ? (
					<p className="text-sm text-muted-foreground">{hints.join(' · ')}</p>
				) : null}
				{uploading ? (
					<p aria-live="polite" className="text-sm text-muted-foreground">
						Uploading
					</p>
				) : null}
				{displayName ? (
					<p className="flex items-center gap-2 text-sm">
						<span>{displayName}</span>
						<button
							type="button"
							className="text-destructive underline"
							onClick={clear}
							disabled={disabled}
						>
							Remove
						</button>
					</p>
				) : null}
				<div id={describedById} className="grid gap-1 text-sm">
					{description ? <p className="text-muted-foreground">{description}</p> : null}
					{invalid ? (
						<div aria-atomic className="text-destructive" role="alert">
							{allErrors.map((message) => (
								<p key={message}>{message}</p>
							))}
						</div>
					) : null}
				</div>
			</div>
		)
	}
)

'use client'

import {
	defineFieldRenderer,
	type SubmissionValue,
	serializeBody,
	useFormContext,
} from '@10x-media/form-builder/react'
import { useMemo } from 'react'

/** Display-only rich text rendered inline between fields; writes nothing to the submission. */
export const messageField = defineFieldRenderer(({ field }) => {
	const { state, effectiveValues } = useFormContext()
	const values = effectiveValues ?? state.values
	const html = useMemo(() => {
		const answered: SubmissionValue[] = Object.entries(values)
			.filter(([, value]) => value != null && value !== '')
			.map(([name, value]) => ({ field: name, value }))
		return serializeBody(field.content, { values: answered, descriptors: [] })
	}, [field.content, values])
	if (html === '') {
		return null
	}
	// Safe to inject: serializeBody HTML-escapes all text (recall values included) and sanitizes link URLs.
	return (
		<div
			className="prose prose-sm max-w-none text-foreground"
			// biome-ignore lint/security/noDangerouslySetInnerHtml: HTML is produced by the package's escaping serializer, never raw user input
			dangerouslySetInnerHTML={{ __html: html }}
		/>
	)
})

