import { defineFieldRenderer } from '@10x-media/form-builder/react'
import { useId } from 'react'
import { Label } from '@/components/ui/label'

/** Read-only renderer for a calculation field: the value is derived, never user-editable, so it
 * shows in an `<output>` rather than an input. */
export const calculationField = defineFieldRenderer<number | undefined>(
	({ field, value, errors, required }) => {
		const id = useId()
		const describedById = `${id}-desc`
		const label = typeof field.label === 'string' ? field.label : undefined
		const description = typeof field.description === 'string' ? field.description : undefined

		return (
			<div className="grid gap-2">
				{label ? (
					<Label htmlFor={id}>
						{label}
						{required ? (
							<span aria-hidden className="text-destructive">
								{' *'}
							</span>
						) : null}
					</Label>
				) : null}
				<output
					id={id}
					aria-describedby={describedById}
					className="flex h-9 w-full items-center rounded-md border border-input bg-muted px-3 py-1 text-sm"
				>
					{value == null ? '' : String(value)}
				</output>
				<div id={describedById} className="grid gap-1 text-sm">
					{description ? <p className="text-muted-foreground">{description}</p> : null}
					{errors.length > 0 ? (
						<div aria-atomic className="text-destructive" role="alert">
							{errors.map((message) => (
								<p key={message}>{message}</p>
							))}
						</div>
					) : null}
				</div>
			</div>
		)
	}
)

'use client'

import {
	defineFieldRenderer,
	type FieldRenderer,
	type FormFieldInstance,
	useFormContext,
} from '@10x-media/form-builder/react'
import { createElement, useId } from 'react'
import { cn } from '@/lib/utils'

type RepeaterRow = Record<string, unknown>

/**
 * Wraps a sub-field renderer as a proper component so hooks keep stable identity per row/field.
 * Reads errors for the composite path `field[row].subField` from form state so server-side
 * validation surfaces inline next to the sub-field, overriding the static values the parent passes.
 */
const SubFieldWrapper = ({
	renderer,
	name,
	...props
}: { renderer: FieldRenderer } & Parameters<FieldRenderer>[0]) => {
	const { state } = useFormContext()
	const errors = (state.errors as Record<string, string[]>)?.[name] ?? []
	return renderer({ ...props, name, errors })
}

export const repeaterField = defineFieldRenderer<RepeaterRow[]>(
	({ field, id: rootId, value, onChange, onBlur, errors, required, locale, t }) => {
		const { rendererRegistry } = useFormContext()
		const addId = useId()
		const invalid = errors.length > 0
		const label = typeof field.label === 'string' ? field.label : undefined
		const description = typeof field.description === 'string' ? field.description : undefined

		const rows = Array.isArray(value) ? value : []
		const subFields = Array.isArray(field.subFields) ? (field.subFields as FormFieldInstance[]) : []
		const maxRows = typeof field.maxRows === 'number' ? field.maxRows : undefined
		const minRows = typeof field.minRows === 'number' ? field.minRows : 0
		const addLabel =
			typeof field.addLabel === 'string' && field.addLabel.length > 0 ? field.addLabel : 'Add row'

		const addRow = () => {
			if (maxRows != null && rows.length >= maxRows) return
			onChange([...rows, {}])
			onBlur()
		}

		const removeRow = (index: number) => {
			onChange(rows.filter((_, i) => i !== index))
			onBlur()
		}

		const updateRow = (index: number, fieldName: string, fieldValue: unknown) => {
			onChange(rows.map((row, i) => (i === index ? { ...row, [fieldName]: fieldValue } : row)))
		}

		return (
			<div className="grid gap-2">
				{label ? (
					<span className="text-sm font-medium leading-none">
						{label}
						{required ? (
							<span aria-hidden className="text-destructive">
								{' *'}
							</span>
						) : null}
					</span>
				) : null}
				<div className="grid gap-4">
					{rows.map((row, rowIndex) => {
						const rowLabel = `Row ${rowIndex + 1}`
						return (
							// biome-ignore lint/suspicious/noArrayIndexKey: repeater rows have no stable id; index key is intentional
							<fieldset key={rowIndex} className="grid gap-3 rounded-md border border-input p-4">
								<legend className="flex items-center gap-3 px-1 text-sm font-medium">
									{rowLabel}
									{rows.length > minRows && (
										<button
											type="button"
											className="text-xs text-destructive underline underline-offset-4"
											onClick={() => removeRow(rowIndex)}
											aria-label={`Remove ${rowLabel}`}
										>
											Remove
										</button>
									)}
								</legend>
								<div className="grid gap-3">
									{subFields.map((subField) => {
										const renderer = rendererRegistry.get(subField.blockType)
										if (!renderer) return null
										const subId = `${rootId}-${rowIndex}-${subField.name}`
										const compositeName = `${field.name}[${rowIndex}].${subField.name}`
										return createElement(SubFieldWrapper, {
											key: subField.name,
											renderer,
											field: subField,
											id: subId,
											name: compositeName,
											value: row[subField.name],
											onChange: (fieldValue: unknown) =>
												updateRow(rowIndex, subField.name, fieldValue),
											onBlur,
											// SubFieldWrapper overrides these from form state; passed here to satisfy the type
											errors: [],
											required: subField.required ?? false,
											disabled: false,
											locale,
											t,
										})
									})}
								</div>
							</fieldset>
						)
					})}
					{(maxRows == null || rows.length < maxRows) && (
						<button
							id={addId}
							type="button"
							className={cn(
								'w-fit rounded-md border border-input px-3 py-1.5 text-sm shadow-sm',
								'hover:bg-accent hover:text-accent-foreground'
							)}
							onClick={addRow}
						>
							{addLabel}
						</button>
					)}
				</div>
				<div className="grid gap-1 text-sm">
					{description ? <p className="text-muted-foreground">{description}</p> : null}
					{invalid ? (
						<div aria-atomic className="text-destructive" role="alert">
							{errors.map((message) => (
								<p key={message}>{message}</p>
							))}
						</div>
					) : null}
				</div>
			</div>
		)
	}
)

'use client'

import { COUNTRIES, defineFieldRenderer, US_STATES } from '@10x-media/form-builder/react'
import { useId } from 'react'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'

/**
 * A `<select>` over a fixed, code-supplied option set for the `country` and `state` field types,
 * whose choices live in the plugin rather than in per-instance `options`. Mirrors `selectField` but
 * takes the options as an argument; the stored value is one of the fixed codes. The option labels are
 * the English names shipped with the plugin and are intentionally not localized.
 */
const regionField = (options: { label: string; value: string }[]) =>
	defineFieldRenderer<string>(
		({ field, name, value, onChange, onBlur, errors, required, disabled }) => {
			const id = useId()
			const describedById = `${id}-desc`
			const invalid = errors.length > 0
			const label = typeof field.label === 'string' ? field.label : undefined
			const description = typeof field.description === 'string' ? field.description : undefined
			const placeholder = typeof field.placeholder === 'string' ? field.placeholder : undefined

			return (
				<div className="grid gap-2">
					{label ? (
						<Label htmlFor={id}>
							{label}
							{required ? (
								<span aria-hidden className="text-destructive">
									{' *'}
								</span>
							) : null}
						</Label>
					) : null}
					<select
						id={id}
						name={name}
						value={value ?? ''}
						required={required}
						disabled={disabled}
						aria-invalid={invalid || undefined}
						aria-describedby={describedById}
						className={cn(
							'flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring',
							invalid && 'border-destructive focus-visible:ring-destructive'
						)}
						onChange={(event) => onChange(event.target.value)}
						onBlur={onBlur}
					>
						{placeholder !== undefined ? <option value="">{placeholder}</option> : null}
						{options.map((option) => (
							<option key={option.value} value={option.value}>
								{option.label}
							</option>
						))}
					</select>
					<div id={describedById} className="grid gap-1 text-sm">
						{description ? <p className="text-muted-foreground">{description}</p> : null}
						{invalid ? (
							<div aria-atomic className="text-destructive" role="alert">
								{errors.map((message) => (
									<p key={message}>{message}</p>
								))}
							</div>
						) : null}
					</div>
				</div>
			)
		}
	)

export const countryField = regionField(COUNTRIES)
export const stateField = regionField(US_STATES)
